import numpy as np
def comps8(I):
    H,W=I.shape; seen=np.zeros_like(I,bool); out=[]
    for i in range(H):
        for j in range(W):
            if seen[i,j] or I[i,j]==0: continue
            stack=[(i,j)]; comp=[]
            while stack:
                a,b=stack.pop()
                if seen[a,b]: continue
                seen[a,b]=True; comp.append((a,b))
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        x,y=a+dx,b+dy
                        if 0<=x<H and 0<=y<W and not seen[x,y] and I[x,y]!=0: stack.append((x,y))
            out.append(comp)
    return out
