import numpy as np
def comps8(I,bg):
    I=np.array(I); H,W=I.shape
    seen=np.zeros_like(I,bool); out=[]
    for r in range(H):
        for c in range(W):
            if I[r,c]!=bg and not seen[r,c]:
                st=[(r,c)]; comp=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in comp or not(0<=a<H and 0<=b<W) or I[a,b]==bg: continue
                    comp.add((a,b)); seen[a,b]=True
                    for da in(-1,0,1):
                        for db in(-1,0,1): st.append((a+da,b+db))
                out.append(comp)
    return out
