            cov=sum(1 for r,c in pl if I[r,c]==bg)
            pc=(sum(r for r,_ in pl)/len(pl), sum(c for _,c in pl)/len(pl))
            hc=(sum(r for r,_ in cs[j])/len(cs[j]), sum(c for _,c in cs[j])/len(cs[j]))
