def comps8(I,bg):
    H,W=I.shape; seen=np.zeros_like(I,bool); out=[]
    for r in range(H):
        for c in range(W):
            if I[r,c]!=bg and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and I[x,y]!=bg and not seen[x,y]:
                                seen[x,y]=True; st.append((x,y))
                out.append(comp)
    return out
# Rule v2: for each seed, try every valid transform/placement of EVERY multi-cell comp
# that CONTAINS the seed's color as a minority cell... no — simpler: allow overwrite anywhere (O==col or kept).
# Then for each seed find placements matching observed output; see how many and what tie-break.
for p in [1,2,5]:
    I=np.array(G[f'Demo pair {p} input']); O=np.array(G[f'Demo pair {p} output'])
    H,W=I.shape
    bg=int(Counter(I.flatten()).most_common(1)[0][0])
    cs=comps8(I,bg)
    hostset=set().union(*[c for c in cs if len(c)>1])
    seeds=[(int(I[r,c]),(r,c)) for r in range(H) for c in range(W) if I[r,c]!=bg and (r,c) not in hostset]
    print('--- demo',p,'seeds:',seeds)
    for col,(sr,sc) in seeds:
        found=[]
        for j in range(len(cs)):
            if len(cs[j])==1: continue
            comp=cs[j]; rs=[a for a,_ in comp]; cc=[b for _,b in comp]
            mm=np.zeros((max(rs)-min(rs)+1,max(cc)-min(cc)+1),bool)
            for r,c in comp: mm[r-min(rs),c-min(cc)]=True
            th,tw=mm.shape
            for tv in dihed(mm.astype(bool)):
                for dr in range(-th+1,H-th+2):
                    for dc in range(-tw+1,W-tw+2):
                        cells=[(dr+rr,dc+c2) for rr in range(th) for c2 in range(tw) if tv[rr,c2]]
                        if not all(0<=r<H and 0<=c<W for r,c in cells): continue
                        if not any(x==(sr,sc) for x in cells): continue
                        good=True
                        for (r,c) in cells:
                            # allow paint over anything; need output consistent
                            if I[r,c]==bg:
                                if O[r,c]!=col: good=False;break
                            elif O[r,c]!=col and O[r,c]!=I[r,c]: good=False;break
                        if good: found.append((j,len(comp),tv.tolist(),tuple(sorted(cells))))
        obs={(r_,c_) for r_ in range(H) for c_ in range(W) if I[r_,c_]==bg and O[r_,c_]==col}
        exact=[x for x in found if set(x[3])==obs]
        print(' seed',col,(sr,sc),'ncand',len(found),'exact-obs',len(exact))

