    seeds=[(int(I[r][c]),(r,c)) for r in range(H) for c in range(W) if I[r][c]!=bg and (r,c) not in any(h[1] for h in hosts)]
    def mindist(sr,sc,hcells):
        return min(max(abs(a-sr),abs(b-sc)) for a,b in hcells)
    # order options
    if order=='near':
        seeds.sort(key=lambda s:mindist(*s[1],next(h[1] for h in hosts if True)))
    O=I.copy()
    occupied=set()  # cells painted by earlier seeds
    for col,(sr,sc) in seeds:
        hi=min(range(len(hosts)),key=lambda j:mindist(sr,sc,hosts[j][1]))
        hc_,hcells=hosts[hi]
        rs_=min(a for a,_ in hcells); cs_=min(b for _,b in hcells)
        th=max(a for a,_ in hcells)-rs_+1; tw=max(b for _,b in hcells)-cs_+1
        mm=np.zeros((th,tw),bool)
        for a,b in hcells: mm[a-rs_,b-cs_]=True
        best=None
        for tv in dihed_mask(mm):
            vh,vw=len(tv),len(tv[0])
            for dr in range(H-vh+1):
                for dc in range(W-vw+1):
                    painted=set()
                    good=True
                    for i in range(vh):
                        for j in range(vw):
                            if tv[i][j]:
                                rr,cc=dr+i,dc+j
                                if (rr,cc)!=(sr,sc):
                                    if I[rr,cc]!=bg: good=False;break
                                    if (rr,cc) in occupied: good=False;break
                                painted.add((rr,cc))
                        if not good: break
                    if not good: continue
                    score=len(painted-{(sr,sc)})
                    if best is None or score>best[0]: best=(score,painted)
        if best:
            for (r,c) in best[1]:
                if I[r][c]==bg: O[r][c]=col
                occupied.add((r,c))
    return O
