def solve(I, orderkey, tiebreak='dist'):
    I=np.array(I); H,W=I.shape
    bg=collections.Counter(I.flatten()).most_common(1)[0][0]
    cs=comps8([list(r) for r in I],bg)
    hosts=[(int(c_),set(cl_)) for c_,cl_ in cs if len(cl_)>1]
    hostcells=set().union(*[h[1] for h in hosts]) if hosts else set()
    seeds=[(int(I[r][c]),(r,c)) for r in range(H) for c in range(W) if I[r][c]!=bg and (r,c) not in hostcells]
    def mindist(sr,sc,hcells):
        return min(max(abs(a-sr),abs(b-sc)) for a,b in hcells)
    orderkey=lambda s:mindist(s[1][0],s[1][1],next(h[1] for h in hosts))
    seeds.sort(key=orderkey)
    occ=set(); O=I.copy()
    for col,(sr,sc) in seeds:
        hi=min(range(len(hosts)),key=lambda j:mindist(sr,sc,hosts[j][1]))
        hc_,hcells=hosts[hi]
        rs_=min(a for a,_ in hcells); cs_=min(b for _,b in hcells)
        th=max(a for a,_ in hcells)-rs_+1; tw=max(b for _,b in hcells)-cs_+1
        mm=np.zeros((th,tw),bool)
        for a,b in hcells: mm[a-rs_,b-cs_]=True
        cands=[]
        for ti,tv in enumerate(dihed_mask(mm)):
            vh,vw=len(tv),len(tv[0])
            for dr in range(H-vh+1):
                for dc in range(W-vw+1):
                    painted=set(); good=True
                    for i in range(vh):
                        for j in range(vw):
                            if tv[i][j]:
                                rr,cc=dr+i,dc+j
                                if (rr,cc)!=(sr,sc):
                                    if I[rr][cc]!=bg or (rr,cc) in occ: good=False;break
                                painted.add((rr,cc))
                        if not good: break
                    if not good: continue
                    # score: maximize painted-bg cells; tie -> prefer adjacency to host
                    nb_bg=len(painted-{(sr,sc)})
                    dhost=min(max(abs(a-sr),abs(b-sc)) for a,b in painted-{(sr,sc)}) if painted>{(sr,sc)} else 99
                    key=(-nb_bg,-dhost,-ti,abs(dr-sr)+abs(dc-sc))
                    cands.append((key,painted))
        if not cands: continue
        best=min(cands,key=lambda x:x[0])[1]
        for (r,c) in best:
            if I[r][c]==bg: O[r][c]=col
            occ.add((r,c))
    return O
