    diffcells={(r,c) for r in range(I.shape[0]) for c in range(I.shape[1]) if int(O[r][c])!=I[r][c]}
    # map each diff cell to its target color
    diffbycol={}
    for r,c in diffcells: diffbycol.setdefault(int(O[r][c]),set()).add((r,c))
    def opts_for(col,d):
        res=[]
        for hi,hc in enumerate(hosts):
            hmr=min(a for a,_ in hc); hmc=min(b for _,b in hc)
            mm=np.zeros((max(1,max(a for a,_ in hc)-hmr+1),max(1,max(b for _,b in hc)-hmc+1)),bool)
            for a,b in hc: mm[a-hmr,b-hmc]=True
            for ti,tv in enumerate(dihed_mask(mm)):
                vh,vw=len(tv),len(tv[0])
                for off_r in range(-6,I.shape[0]-vh+1):
                    for off_c in range(-6,I.shape[1]-vw+1):
                        pp={(off_r+i,off_c+j) for i in range(vh) for j in range(vw) if tv[i][j]}
                        pp={q for q in pp if 0<=q[0]<I.shape[0] and 0<=q[1]<I.shape[1]}
                        painted=pp
                        # painted includes seed cells allowed; requires painted subset of (diffofcol + hostcells? no host cells are bg? host is colored so no) 
                        if painted <= (d|hostcells):  # allow touching host? exclude if paints host cells
                            pass
                        if painted & hostcells: continue
                        res.append((hi,ti,painted,mindist(pp,hc)))
        return res
    pool={k:v for k,v in [(col,list(opts_for(k,d))) for col,d in diffbycol.items()]}
    # order by fewest options
    order=sorted(diffbycol,key=lambda k:len(pool[k]))
    chosen=[]; used=set()
    for col in order:
        ds=list(pool[col])
        cand=[o for o in ds if not (o[2]&used)]
        if not cand: return None,'FAIL '+str(col)
        pick=min(cand,key=lambda o:o[3])   # nearest host first
        chosen.append((col,pick))
        used|=pick[2]
    return used==diffcells,chosen
